mapper.select:


    inner join sys_user u on u.user_name = dequipmentmaintenanceday.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'

left join d_equipment e ON dequipmentmaintenanceday.equipment_id = e.id
left join sys_user z ON z.user_id = dequipmentmaintenanceday.executor_id

    dequipmentmaintenanceday.del_flag = '0'
     and dequipmentmaintenanceday.equipment_id = #{equipmentId}
     and dequipmentmaintenanceday.part_name like concat('%', #{partName}, '%')
     and dequipmentmaintenanceday.content = #{content}
     and dequipmentmaintenanceday.maintenance_type = #{maintenanceType}
     and dequipmentmaintenanceday.is_external = #{isExternal}
     and dequipmentmaintenanceday.external_company = #{externalCompany}
     and dequipmentmaintenanceday.plan_day = #{planDay}
     and dequipmentmaintenanceday.true_day = #{trueDay}
     and dequipmentmaintenanceday.executor_id = #{executorId}
     and z.user_name like concat('%', #{executorName}, '%')
     and dequipmentmaintenanceday.status = #{status}
     and dequipmentmaintenanceday.type = #{type}
     and dequipmentmaintenanceday.source = #{source}
     and e.name like concat('%', #{equName}, '%')
     and dequipmentmaintenanceday.day_no = #{dayNo}
     and DATE_FORMAT(create_time,"%Y-%m-%d") = #{createTimeSearch}
     and dequipmentmaintenanceday.equ_fault_lv = #{equFaultLv}






${params.dataScope}
